DEFAULT_OUT = ROOT / "outputs" / "joint_innovation_field_v84_2026-07-17"
EPS = 1e-8


@dataclass
class AnchorBundle:
    name: str
    rows: pd.DataFrame
    anchor_residual: np.ndarray
    base: np.ndarray
    target_steps: np.ndarray
    meta: dict[str, Any]

    @property
    def anchor_steps(self) -> np.ndarray:
        residual = self.anchor_residual.reshape(len(self.rows), -1, 2)
        return self.base[:, None, :] + residual

    @property
    def errors(self) -> np.ndarray:
        return self.target_steps - self.anchor_steps


@dataclass(frozen=True)
class FieldConfig:
    grid: int
    sigma: float
    ridge: float

    @property
    def name(self) -> str:
        return f"g{self.grid}_s{self.sigma:g}_r{self.ridge:g}"


@dataclass
class FieldFrames:
    keys: list[tuple[int, int]]
    coeff: np.ndarray  # [frame, step, coefficient]
    count: np.ndarray
    state: np.ndarray
    state_names: list[str]


def finite_json(value: Any) -> Any:
    return audit.finite_json(value)


def parse_strs(value: str | Iterable[str]) -> list[str]:
    if isinstance(value, str):
        return [x.strip() for x in value.split(",") if x.strip()]
    return [str(x) for x in value]


def parse_ints(value: str | Iterable[int]) -> list[int]:
    return [int(float(x)) for x in parse_strs(value)]


def parse_floats(value: str | Iterable[float]) -> list[float]:
    return [float(x) for x in parse_strs(value)]


def safe(x: Any) -> np.ndarray:
    return np.nan_to_num(np.asarray(x, dtype=np.float32), nan=0.0, posinf=0.0, neginf=0.0).astype(np.float32)


def stable_hash(payload: dict[str, Any]) -> str:
    text = json.dumps(finite_json(payload), sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]


def component_rmse(y: np.ndarray, p: np.ndarray) -> float:
    return float(np.sqrt(np.mean(np.square(safe(y) - safe(p)))))


def vector_rmse(y: np.ndarray, p: np.ndarray) -> float:
    return float(np.sqrt(np.mean(np.sum(np.square(safe(y) - safe(p)), axis=-1))))


def vector_r2(y: np.ndarray, p: np.ndarray) -> float:
    yy = safe(y)
    pp = safe(p)
    sse = float(np.sum(np.square(yy - pp)))
    sst = float(np.sum(np.square(yy - yy.mean(axis=0, keepdims=True))))
    return float(1.0 - sse / max(sst, EPS))


def cosine_mean(y: np.ndarray, p: np.ndarray) -> float:
    yy = safe(y)
    pp = safe(p)
    den = np.maximum(np.linalg.norm(yy, axis=1) * np.linalg.norm(pp, axis=1), EPS)
    return float(np.mean(np.sum(yy * pp, axis=1) / den))


def magnitude_ratio(y: np.ndarray, p: np.ndarray) -> float:
    return float(np.mean(np.linalg.norm(safe(p), axis=1)) / max(float(np.mean(np.linalg.norm(safe(y), axis=1))), EPS))


def metric_rows(
    bundle: AnchorBundle,
    pred_steps: np.ndarray,
    horizons: list[int],
    method: str,
    extra: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for h in horizons:
        y = bundle.target_steps[:, :h].sum(axis=1)
        p = safe(pred_steps)[:, :h].sum(axis=1)
        row: dict[str, Any] = {
            "method": method,
            "horizon": int(h),
            "component_rmse": component_rmse(y, p),
            "vector_rmse": vector_rmse(y, p),
            "r2": vector_r2(y, p),
            "cosine": cosine_mean(y, p),
            "magnitude_ratio": magnitude_ratio(y, p),
            "n_rows": int(len(y)),
        }
        if extra:
            row.update(extra)
        rows.append(row)
    return rows


def anchor_contract(args: argparse.Namespace, train: list[int], val: list[int], test: list[int], seed: int) -> dict[str, Any]:
    return {
        "dataset": args.dataset,
        "features": str(Path(args.features).resolve()),
        "train_seq": train,
        "val_seq": val,
        "test_seq": test,
        "seed": int(seed),
        "max_horizon": int(args.max_horizon),
        "anchor_max_train_rows": int(args.anchor_max_train_rows),
        "anchor_max_val_rows": int(args.anchor_max_val_rows),
        "anchor_max_test_rows": int(args.anchor_max_test_rows),
        "posterior_epochs": int(args.posterior_epochs),
        "student_epochs": int(args.student_epochs),
        "route_k": int(args.v12_route_k),
        "v52_base_mix": args.v70_v52_base_mix,
        "v52_calibrator": args.v70_v52_calibrator,
        "local_ks": args.local_ks,
        "local_radii": args.local_radii,
    }


def minimal_row_frame(df: pd.DataFrame, max_horizon: int) -> pd.DataFrame:
    cols = ["dataset", "sequence", "frame", "track_id", "x_px", "y_px", "dx_px", "dy_px"]
    for h in range(1, int(max_horizon) + 1):
        cols.extend([f"step{h}_dx", f"step{h}_dy"])
    present = [c for c in cols if c in df.columns]
    out = df[present].copy().reset_index(drop=True)
    out["sequence"] = out["sequence"].astype(int)
    out["frame"] = out["frame"].astype(int)
    out["track_id"] = out["track_id"].astype(int)
    return out


def save_bundle(path: Path, bundle: AnchorBundle) -> None:
    path.mkdir(parents=True, exist_ok=True)
    bundle.rows.to_csv(path / "rows.csv", index=False)
    np.savez_compressed(
        path / "arrays.npz",
        anchor_residual=safe(bundle.anchor_residual),
        base=safe(bundle.base),
        target_steps=safe(bundle.target_steps),
    )
    (path / "meta.json").write_text(json.dumps(finite_json(bundle.meta), indent=2), encoding="utf-8")


def load_bundle(path: Path, name: str) -> AnchorBundle:
    rows = pd.read_csv(path / "rows.csv")
    arrays = np.load(path / "arrays.npz")
    meta = json.loads((path / "meta.json").read_text(encoding="utf-8"))
    return AnchorBundle(
        name=name,
        rows=rows,
        anchor_residual=safe(arrays["anchor_residual"]),
        base=safe(arrays["base"]),
        target_steps=safe(arrays["target_steps"]),
        meta=meta,
    )


def build_exact_anchor(
    args: argparse.Namespace,
    *,
    name: str,
    train_seq: list[int],
    val_seq: list[int],
    test_seq: list[int],
    seed: int,
) -> dict[str, AnchorBundle]:
    contract = anchor_contract(args, train_seq, val_seq, test_seq, seed)
    key = stable_hash(contract)
    cache = args.anchor_cache / f"{name}_{key}"
    required = [cache / split / "arrays.npz" for split in ("train", "val", "test")]
    if not bool(args.rebuild_anchors) and all(p.exists() for p in required):
        return {split: load_bundle(cache / split, f"{name}_{split}") for split in ("train", "val", "test")}

    local = copy.copy(args)
    local.out_dir = cache / "runner"
    local.train_seq = ",".join(map(str, train_seq))
    local.val_seq = ",".join(map(str, val_seq))
    local.test_seq = ",".join(map(str, test_seq))
    local.seed = int(seed)
    local.max_train_rows = int(args.anchor_max_train_rows)
    local.max_val_rows = int(args.anchor_max_val_rows)
    local.max_test_rows = int(args.anchor_max_test_rows)
    local.generator_max_train_rows = int(args.anchor_max_train_rows)
    local.generator_max_val_rows = int(args.anchor_max_val_rows)
    local.generator_max_test_rows = int(args.anchor_max_test_rows)
    local.horizons = list(args.horizons)
    local.flow_packets = "real"
    local.out_dir.mkdir(parents=True, exist_ok=True)
    route_basis_dir = local.out_dir / "route_basis"
    route_basis_dir.mkdir(parents=True, exist_ok=True)

    basis, route_meta, gate = v72.build_route_basis(local, route_basis_dir)
    anchor, anchor_meta = v70.build_v52_anchor(basis, local)
    split_map = {"train": basis.split.train, "val": basis.split.val, "test": basis.split.test}
    base_map = {"train": basis.arrays.base_train, "val": basis.arrays.base_val, "test": basis.arrays.base_test}
    target_map = {"train": basis.arrays.steps_train, "val": basis.arrays.steps_val, "test": basis.arrays.steps_test}

    bundles: dict[str, AnchorBundle] = {}
    for split in ("train", "val", "test"):
        rows = minimal_row_frame(split_map[split], local.max_horizon)
        pred = safe(anchor[split])
        if len(rows) != len(pred):
            raise RuntimeError(f"anchor/row mismatch for {name}/{split}: {len(pred)} vs {len(rows)}")
        meta = {
            "name": name,
            "split": split,
            "contract": contract,
            "route_meta": route_meta,
            "route_gate": gate.to_dict(orient="records") if isinstance(gate, pd.DataFrame) else [],
            "anchor_meta": anchor_meta,
            "row_count": int(len(rows)),
        }
        bundle = AnchorBundle(name=f"{name}_{split}", rows=rows, anchor_residual=pred, base=safe(base_map[split]), target_steps=safe(target_map[split]), meta=meta)
        save_bundle(cache / split, bundle)
        bundles[split] = bundle
    (cache / "contract.json").write_text(json.dumps(finite_json(contract), indent=2), encoding="utf-8")
    return bundles


def concat_bundles(name: str, bundles: list[AnchorBundle]) -> AnchorBundle:
    rows = pd.concat([b.rows for b in bundles], ignore_index=True)
    anchor = np.concatenate([b.anchor_residual for b in bundles], axis=0)
    base = np.concatenate([b.base for b in bundles], axis=0)
    target = np.concatenate([b.target_steps for b in bundles], axis=0)
    order = np.lexsort((rows["track_id"].to_numpy(), rows["frame"].to_numpy(), rows["sequence"].to_numpy()))
    rows = rows.iloc[order].reset_index(drop=True)
    return AnchorBundle(name=name, rows=rows, anchor_residual=anchor[order], base=base[order], target_steps=target[order], meta={"parts": [b.name for b in bundles]})


def build_anchor_sets(args: argparse.Namespace) -> tuple[AnchorBundle, AnchorBundle, AnchorBundle, pd.DataFrame]:
    train_movies = parse_ints(args.train_seq)
    final = build_exact_anchor(
        args,
        name="final",
        train_seq=train_movies,
        val_seq=parse_ints(args.val_seq),
        test_seq=parse_ints(args.test_seq),
        seed=int(args.seed),
    )

    oof: list[AnchorBundle] = []
    quality_rows: list[dict[str, Any]] = []
    folds = train_movies[: int(args.oof_fold_limit)] if int(args.oof_fold_limit) > 0 else train_movies
    for fold_idx, heldout in enumerate(folds):
        remaining = [s for s in train_movies if s != heldout]
        fold_val = remaining[-1]
        fold_train = remaining[:-1]
        fold = build_exact_anchor(
            args,
            name=f"oof_seq{heldout:02d}",
            train_seq=fold_train,
            val_seq=[fold_val],
            test_seq=[heldout],
            seed=int(args.seed) + 100 + fold_idx,
        )["test"]
        oof.append(fold)
        quality_rows.extend(metric_rows(fold, fold.anchor_steps, args.horizons, "oof_v52_anchor", {"heldout_sequence": int(heldout)}))

    if set(folds) != set(train_movies):
        # Smoke mode may intentionally build a subset of folds. It is valid for
        # plumbing only and is marked explicitly in every output.
        train = concat_bundles("oof_train_partial", oof)
    else:
        train = concat_bundles("oof_train", oof)
    val = final["val"]
    test = final["test"]
    quality_rows.extend(metric_rows(val, val.anchor_steps, args.horizons, "final_v52_anchor_val", {}))
    quality_rows.extend(metric_rows(test, test.anchor_steps, args.horizons, "final_v52_anchor_test", {}))
    return train, val, test, pd.DataFrame(quality_rows)


def fit_xy_norm(train: AnchorBundle) -> tuple[np.ndarray, np.ndarray]:
    xy = train.rows[["x_px", "y_px"]].to_numpy(np.float32)
    lo = np.quantile(xy, 0.01, axis=0).astype(np.float32)
    hi = np.quantile(xy, 0.99, axis=0).astype(np.float32)
    return lo, np.maximum(hi - lo, 1.0).astype(np.float32)


def normalize_xy(xy: np.ndarray, lo: np.ndarray, scale: np.ndarray) -> np.ndarray:
    return np.clip(2.0 * (safe(xy) - lo[None, :]) / scale[None, :] - 1.0, -1.5, 1.5).astype(np.float32)


def grid_centers(grid: int) -> np.ndarray:
    axis = np.linspace(-0.9, 0.9, int(grid), dtype=np.float32)
    xx, yy = np.meshgrid(axis, axis, indexing="xy")
    return np.stack([xx.reshape(-1), yy.reshape(-1)], axis=1).astype(np.float32)


def hodge_design(xy: np.ndarray, config: FieldConfig) -> np.ndarray:
    """Return vector basis [N, 2, D] for grad/curl Gaussian potentials."""
    x = safe(xy)
    centers = grid_centers(config.grid)
    delta = x[:, None, :] - centers[None, :, :]
    sigma2 = max(float(config.sigma) ** 2, 1e-5)
    radial = np.exp(-0.5 * np.sum(delta * delta, axis=2) / sigma2).astype(np.float32)
    grad = (-delta / sigma2) * radial[:, :, None]
    curl = np.stack([-grad[:, :, 1], grad[:, :, 0]], axis=2)
    n, m, _ = grad.shape
    out = np.zeros((n, 2, 2 * m + 2), dtype=np.float32)
    out[:, :, :m] = np.transpose(grad, (0, 2, 1))
    out[:, :, m : 2 * m] = np.transpose(curl, (0, 2, 1))
    out[:, 0, 2 * m] = 1.0
    out[:, 1, 2 * m + 1] = 1.0
    return out


def fit_field_coeff(design: np.ndarray, vector: np.ndarray, ridge: float) -> np.ndarray:
    a = safe(design).reshape(-1, design.shape[-1]).astype(np.float64)
    y = safe(vector).reshape(-1).astype(np.float64)
    gram = a.T @ a
    reg = float(ridge) * np.eye(gram.shape[0], dtype=np.float64)
    coef = np.linalg.solve(gram + reg, a.T @ y)
    return coef.astype(np.float32)


def eval_field(design: np.ndarray, coeff: np.ndarray) -> np.ndarray:
    return np.einsum("ncd,d->nc", safe(design), safe(coeff), optimize=True).astype(np.float32)


def frame_groups(bundle: AnchorBundle) -> list[tuple[tuple[int, int], np.ndarray]]:
    groups = bundle.rows.groupby(["sequence", "frame"], sort=True).indices
    return [((int(seq), int(frame)), np.asarray(idx, dtype=np.int64)) for (seq, frame), idx in groups.items()]


def frame_state(bundle: AnchorBundle, idx: np.ndarray) -> tuple[np.ndarray, list[str]]:
    base = bundle.base[idx]
    speed = np.linalg.norm(base, axis=1)
    xy = bundle.rows.iloc[idx][["x_px", "y_px"]].to_numpy(np.float32)
    cov = np.cov(base.T) if len(base) > 2 else np.zeros((2, 2), dtype=np.float32)
    values = np.asarray(
        [
            base[:, 0].mean(),
            base[:, 1].mean(),
            base[:, 0].std(),
            base[:, 1].std(),
            speed.mean(),
            speed.std(),
            float(cov[0, 0]),
            float(cov[0, 1]),
            float(cov[1, 1]),
            float(len(idx)),
            xy[:, 0].mean(),
            xy[:, 1].mean(),
        ],
        dtype=np.float32,
    )
    names = ["mean_vx", "mean_vy", "std_vx", "std_vy", "mean_speed", "std_speed", "cov_xx", "cov_xy", "cov_yy", "cell_count", "centroid_x", "centroid_y"]
    return values, names


def cross_cell_reconstruction(
    bundle: AnchorBundle,
    config: FieldConfig,
    lo: np.ndarray,
    scale: np.ndarray,
    steps: list[int],
    seed: int,
    control: str = "real",
) -> dict[str, float]:
    rng = np.random.default_rng(int(seed))
    total_sse = {s: 0.0 for s in steps}
    total_zero = {s: 0.0 for s in steps}
    total_count = {s: 0 for s in steps}
    frames = 0
    for (_key, idx) in frame_groups(bundle):
        # Ridge regularization makes the basis identifiable even when the
        # number of cells is smaller than the number of coefficients.  Keep a
        # modest floor so sparse smoke subsets exercise the same code path.
        if len(idx) < max(8, config.grid * config.grid):
            continue
        rows = bundle.rows.iloc[idx]
        hashes = (rows["track_id"].to_numpy(np.int64) * 31 + rows["frame"].to_numpy(np.int64)) % 5
        fit_mask = hashes != 0
        test_mask = ~fit_mask
        if fit_mask.sum() < 6 or test_mask.sum() < 2:
            continue
        xy = normalize_xy(rows[["x_px", "y_px"]].to_numpy(np.float32), lo, scale)
        design = hodge_design(xy, config)
        errors = bundle.errors[idx].copy()
        if control == "row_shuffled":
            errors = errors[rng.permutation(len(errors))]
        elif control == "random_positions":
            design = hodge_design(xy[rng.permutation(len(xy))], config)
        for s in steps:
            y = errors[:, int(s) - 1]
            coeff = fit_field_coeff(design[fit_mask], y[fit_mask], config.ridge)
            pred = eval_field(design[test_mask], coeff)
            truth = bundle.errors[idx[test_mask], int(s) - 1]
            total_sse[s] += float(np.sum(np.square(pred - truth)))
            total_zero[s] += float(np.sum(np.square(truth)))
            total_count[s] += int(truth.size)
        frames += 1
    out: dict[str, float] = {"frames": float(frames)}
    for s in steps:
        out[f"explained_step{s}"] = float(1.0 - total_sse[s] / max(total_zero[s], EPS))
        out[f"component_rmse_step{s}"] = float(math.sqrt(total_sse[s] / max(1, total_count[s])))
    return out


def field_config_sweep(
    train: AnchorBundle,
    val: AnchorBundle,
    test: AnchorBundle,
    args: argparse.Namespace,
    lo: np.ndarray,
    scale: np.ndarray,
) -> tuple[FieldConfig, pd.DataFrame]:
    rows: list[dict[str, Any]] = []
    steps = sorted(set([1, int(args.max_horizon)]))
    for grid in parse_ints(args.field_grids):
        for sigma in parse_floats(args.field_sigmas):
            for ridge in parse_floats(args.field_ridges):
                cfg = FieldConfig(grid, sigma, ridge)
                for split_name, bundle in (("train", train), ("val", val)):
                    result = cross_cell_reconstruction(bundle, cfg, lo, scale, steps, int(args.seed) + grid * 100, "real")
                    rows.append({"config": cfg.name, "grid": grid, "sigma": sigma, "ridge": ridge, "split": split_name, "control": "real", **result})
    sweep = pd.DataFrame(rows)
    val_rows = sweep[(sweep["split"].eq("val")) & (sweep["control"].eq("real"))].copy()
    score_cols = [f"explained_step{s}" for s in steps]
    val_rows["selection_score"] = val_rows[score_cols].mean(axis=1)
    best_row = val_rows.sort_values(["selection_score", "grid"], ascending=[False, True]).iloc[0]
    best = FieldConfig(int(best_row["grid"]), float(best_row["sigma"]), float(best_row["ridge"]))
    for split_name, bundle in (("test", test),):
        for control in ("real", "row_shuffled", "random_positions"):
            result = cross_cell_reconstruction(bundle, best, lo, scale, steps, int(args.seed) + 8400, control)
            sweep = pd.concat([sweep, pd.DataFrame([{"config": best.name, "grid": best.grid, "sigma": best.sigma, "ridge": best.ridge, "split": split_name, "control": control, **result}])], ignore_index=True)
    return best, sweep


def fit_frame_coefficients(bundle: AnchorBundle, config: FieldConfig, lo: np.ndarray, scale: np.ndarray) -> FieldFrames:
    keys: list[tuple[int, int]] = []
    coeffs: list[np.ndarray] = []
    counts: list[int] = []
    states: list[np.ndarray] = []
    state_names: list[str] = []
    for key, idx in frame_groups(bundle):
        xy = normalize_xy(bundle.rows.iloc[idx][["x_px", "y_px"]].to_numpy(np.float32), lo, scale)
        design = hodge_design(xy, config)
        step_coeff = [fit_field_coeff(design, bundle.errors[idx, s], config.ridge) for s in range(bundle.errors.shape[1])]
        state, state_names = frame_state(bundle, idx)
        keys.append(key)
        coeffs.append(np.stack(step_coeff, axis=0))
        counts.append(len(idx))
        states.append(state)
    return FieldFrames(keys=keys, coeff=safe(np.stack(coeffs)), count=np.asarray(counts, dtype=np.int32), state=safe(np.stack(states)), state_names=state_names)


def make_frame_supervision(frames: FieldFrames, lags: int, control: str, seed: int) -> tuple[np.ndarray, np.ndarray, list[tuple[int, int]]]:
    by_seq: dict[int, list[int]] = {}
    for i, (seq, _frame) in enumerate(frames.keys):
        by_seq.setdefault(int(seq), []).append(i)
    xs: list[np.ndarray] = []
    ys: list[np.ndarray] = []
    keys: list[tuple[int, int]] = []
    rng = np.random.default_rng(int(seed))
    for seq, ids in sorted(by_seq.items()):
        ids = sorted(ids, key=lambda i: frames.keys[i][1])
        h1 = frames.coeff[ids, 0, :].copy()
        state = frames.state[ids].copy()
        if control == "time_shuffled":
            h1 = h1[rng.permutation(len(h1))]
        elif control == "wrong_movie":
            h1 = np.roll(h1, max(1, len(h1) // 3), axis=0)
        for pos in range(int(lags), len(ids)):
            hist = h1[pos - int(lags) : pos]
            mask = np.ones((int(lags), 1), dtype=np.float32)
            x = np.concatenate([hist.reshape(-1), mask.reshape(-1), state[pos]], axis=0)
            xs.append(x.astype(np.float32))
            ys.append(frames.coeff[ids[pos]].reshape(-1).astype(np.float32))
            keys.append(frames.keys[ids[pos]])
    return safe(np.stack(xs)), safe(np.stack(ys)), keys


def coefficient_predictions_to_rows(
    bundle: AnchorBundle,
    keys: list[tuple[int, int]],
    prediction: np.ndarray,
    config: FieldConfig,
    lo: np.ndarray,
    scale: np.ndarray,
) -> np.ndarray:
    h = bundle.target_steps.shape[1]
    d = hodge_design(np.zeros((1, 2), dtype=np.float32), config).shape[-1]
    pred = safe(prediction).reshape(len(keys), h, d)
    out = np.zeros_like(bundle.target_steps, dtype=np.float32)
    lookup = {key: pred[i] for i, key in enumerate(keys)}
    for key, idx in frame_groups(bundle):
        coeff = lookup.get(key)
        if coeff is None:
            continue
        xy = normalize_xy(bundle.rows.iloc[idx][["x_px", "y_px"]].to_numpy(np.float32), lo, scale)
        design = hodge_design(xy, config)
        for step in range(h):
            out[idx, step] = eval_field(design, coeff[step])
    return out


def tune_eta(bundle: AnchorBundle, correction: np.ndarray, horizons: list[int], grid: list[float]) -> tuple[float, float]:
    best_eta = 0.0
    best = float("inf")
    for eta in grid:
        pred = bundle.anchor_steps + float(eta) * safe(correction)
        errors = []
        for h in horizons:
            y = bundle.target_steps[:, :h].sum(axis=1)
            p = pred[:, :h].sum(axis=1)
            errors.append(float(np.mean(np.square(y - p))))
        score = float(math.sqrt(np.mean(errors)))
        if score < best:
            best = score
            best_eta = float(eta)
    return best_eta, best


def fit_direct_ridge(
    xtr: np.ndarray,
    ytr: np.ndarray,
    xva: np.ndarray,
    yva: np.ndarray,
    xte: np.ndarray,
    alphas: list[float],
) -> tuple[np.ndarray, np.ndarray, float, float]:
    sx = StandardScaler()
    sy = StandardScaler()
    ztr = np.clip(np.nan_to_num(sx.fit_transform(xtr)), -8.0, 8.0)
    zva = np.clip(np.nan_to_num(sx.transform(xva)), -8.0, 8.0)
    zte = np.clip(np.nan_to_num(sx.transform(xte)), -8.0, 8.0)
    ty = sy.fit_transform(ytr)
    best: tuple[float, Ridge, float] | None = None
    for alpha in alphas:
        model = Ridge(alpha=float(alpha), solver="lsqr")
        model.fit(ztr, ty)
        pv = sy.inverse_transform(model.predict(zva)).astype(np.float32)
        score = float(np.sqrt(np.mean(np.square(pv - yva))))
        if best is None or score < best[0]:
            best = (score, model, float(alpha))
    assert best is not None
    return (
        sy.inverse_transform(best[1].predict(zva)).astype(np.float32),
        sy.inverse_transform(best[1].predict(zte)).astype(np.float32),
        best[2],
        best[0],
    )


def frame_forecast_experiments(
    train_bundle: AnchorBundle,
    val_bundle: AnchorBundle,
    test_bundle: AnchorBundle,
    train_frames: FieldFrames,
    val_frames: FieldFrames,
    test_frames: FieldFrames,
    config: FieldConfig,
    lo: np.ndarray,
    scale: np.ndarray,
    args: argparse.Namespace,
) -> tuple[pd.DataFrame, pd.DataFrame, np.ndarray]:
    metrics: list[dict[str, Any]] = []
    diagnostics: list[dict[str, Any]] = []
    best_test_correction = np.zeros_like(test_bundle.target_steps)
    best_test_score = float("inf")
    eta_grid = parse_floats(args.correction_eta_grid)
    for control in ("real", "time_shuffled", "wrong_movie"):
        xtr, ytr, ktr = make_frame_supervision(train_frames, int(args.field_lags), control, int(args.seed) + 1)
        xva, yva, kva = make_frame_supervision(val_frames, int(args.field_lags), control, int(args.seed) + 2)
        xte, yte, kte = make_frame_supervision(test_frames, int(args.field_lags), control, int(args.seed) + 3)
        pva, pte, alpha, coeff_val_rmse = fit_direct_ridge(xtr, ytr, xva, yva, xte, parse_floats(args.field_forecast_alphas))
        corr_val = coefficient_predictions_to_rows(val_bundle, kva, pva, config, lo, scale)
        corr_test = coefficient_predictions_to_rows(test_bundle, kte, pte, config, lo, scale)
        eta, val_score = tune_eta(val_bundle, corr_val, args.horizons, eta_grid)
        pred = test_bundle.anchor_steps + eta * corr_test
        label = f"v84_field_ridge_{control}"
        metrics.extend(metric_rows(test_bundle, pred, args.horizons, label, {"stage": "field_forecast", "control": control, "eta": eta, "alpha": alpha, "val_score": val_score}))
        diagnostics.append({"method": label, "control": control, "train_frames": len(ktr), "val_frames": len(kva), "test_frames": len(kte), "feature_dim": xtr.shape[1], "target_dim": ytr.shape[1], "alpha": alpha, "coefficient_val_rmse": coeff_val_rmse, "eta": eta, "val_score": val_score})
        hmax = max(args.horizons)
        test_row = [r for r in metrics if r["method"] == label and r["horizon"] == hmax][0]
        if control == "real" and float(test_row["component_rmse"]) < best_test_score:
            best_test_score = float(test_row["component_rmse"])
            best_test_correction = eta * corr_test

    # A no-learning causal persistence control: repeat the latest observed h1
    # innovation field over all future steps.
    _xva, _yva, kva = make_frame_supervision(val_frames, int(args.field_lags), "real", int(args.seed) + 11)
    _xte, _yte, kte = make_frame_supervision(test_frames, int(args.field_lags), "real", int(args.seed) + 12)
    d = test_frames.coeff.shape[-1]
    def persistence(frames: FieldFrames, keys: list[tuple[int, int]]) -> np.ndarray:
        lookup = {k: i for i, k in enumerate(frames.keys)}
        out = []
        for seq, frame in keys:
            prev_ids = [i for i, (s, f) in enumerate(frames.keys) if s == seq and f < frame]
            coeff = frames.coeff[max(prev_ids), 0] if prev_ids else np.zeros((d,), np.float32)
            out.append(np.tile(coeff[None, :], (int(args.max_horizon), 1)).reshape(-1))
        return safe(np.stack(out))
    pva = persistence(val_frames, kva)
    pte = persistence(test_frames, kte)
    corr_val = coefficient_predictions_to_rows(val_bundle, kva, pva, config, lo, scale)
    corr_test = coefficient_predictions_to_rows(test_bundle, kte, pte, config, lo, scale)
    eta, val_score = tune_eta(val_bundle, corr_val, args.horizons, eta_grid)
    metrics.extend(metric_rows(test_bundle, test_bundle.anchor_steps + eta * corr_test, args.horizons, "v84_field_persistence", {"stage": "field_forecast", "control": "persistence", "eta": eta, "val_score": val_score}))
    diagnostics.append({"method": "v84_field_persistence", "control": "persistence", "eta": eta, "val_score": val_score})
    return pd.DataFrame(metrics), pd.DataFrame(diagnostics), best_test_correction


def lagged_self_innovation_features(bundle: AnchorBundle, max_lag: int) -> tuple[np.ndarray, np.ndarray]:
    err1 = bundle.errors[:, 0]
    key_to_idx = {(int(r.sequence), int(r.frame), int(r.track_id)): i for i, r in bundle.rows[["sequence", "frame", "track_id"]].iterrows()}
    feats = np.zeros((len(bundle.rows), int(max_lag) * 3), dtype=np.float32)
    coverage = np.zeros((len(bundle.rows), int(max_lag)), dtype=np.float32)
    for i, row in enumerate(bundle.rows[["sequence", "frame", "track_id"]].itertuples(index=False)):
        for lag in range(1, int(max_lag) + 1):
            j = key_to_idx.get((int(row.sequence), int(row.frame) - lag, int(row.track_id)))
            if j is None:
                continue
            offset = (lag - 1) * 3
            feats[i, offset : offset + 2] = err1[j]
            feats[i, offset + 2] = 1.0
            coverage[i, lag - 1] = 1.0
    return feats, coverage


def fit_cell_innovation_models(
    train: AnchorBundle,
    val: AnchorBundle,
    test: AnchorBundle,
    field_test_correction: np.ndarray,
    args: argparse.Namespace,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    lag = int(args.self_innovation_lags)
    xtr_lag, ctr = lagged_self_innovation_features(train, lag)
    xva_lag, cva = lagged_self_innovation_features(val, lag)
    xte_lag, cte = lagged_self_innovation_features(test, lag)
    anchor_tr = train.anchor_residual.astype(np.float32)
    anchor_va = val.anchor_residual.astype(np.float32)
    anchor_te = test.anchor_residual.astype(np.float32)
    state_tr = np.concatenate([train.base, np.linalg.norm(train.base, axis=1, keepdims=True), anchor_tr], axis=1)
    state_va = np.concatenate([val.base, np.linalg.norm(val.base, axis=1, keepdims=True), anchor_va], axis=1)
    state_te = np.concatenate([test.base, np.linalg.norm(test.base, axis=1, keepdims=True), anchor_te], axis=1)
    ytr = train.errors.reshape(len(train.rows), -1)
    yva = val.errors.reshape(len(val.rows), -1)
    metrics: list[dict[str, Any]] = []
    diag: list[dict[str, Any]] = []
    rng = np.random.default_rng(int(args.seed) + 8421)

    variants = {
        "state_only": (state_tr, state_va, state_te),
        "self_innovation": (np.concatenate([state_tr, xtr_lag], axis=1), np.concatenate([state_va, xva_lag], axis=1), np.concatenate([state_te, xte_lag], axis=1)),
        "self_innovation_shuffled": (np.concatenate([state_tr, xtr_lag[rng.permutation(len(xtr_lag))]], axis=1), np.concatenate([state_va, xva_lag[rng.permutation(len(xva_lag))]], axis=1), np.concatenate([state_te, xte_lag[rng.permutation(len(xte_lag))]], axis=1)),
    }
    for name, (xtr, xva, xte) in variants.items():
        pva, pte, alpha, val_resid_rmse = fit_direct_ridge(xtr, ytr, xva, yva, xte, parse_floats(args.cell_ridge_alphas))
        corr_va = pva.reshape(val.errors.shape)
        corr_te = pte.reshape(test.errors.shape)
        eta, val_score = tune_eta(val, corr_va, args.horizons, parse_floats(args.correction_eta_grid))
        pred = test.anchor_steps + eta * corr_te
        method = f"v84_cell_ridge_{name}"
        metrics.extend(metric_rows(test, pred, args.horizons, method, {"stage": "cell_innovation", "variant": name, "eta": eta, "alpha": alpha, "val_score": val_score}))
        diag.append({"method": method, "variant": name, "feature_dim": xtr.shape[1], "alpha": alpha, "val_residual_rmse": val_resid_rmse, "eta": eta, "val_score": val_score, "train_lag1_coverage": float(ctr[:, 0].mean()), "val_lag1_coverage": float(cva[:, 0].mean()), "test_lag1_coverage": float(cte[:, 0].mean())})

    # The field correction is already validation-gated. A second residual model
    # is allowed only as a bounded cell-specific remainder around that field.
    if np.any(np.abs(field_test_correction) > 0):
        metrics.extend(metric_rows(test, test.anchor_steps + field_test_correction, args.horizons, "v84_joint_field_safe", {"stage": "joint_safe"}))
    return pd.DataFrame(metrics), pd.DataFrame(diag)


def write_report(
    args: argparse.Namespace,
    anchor_metrics: pd.DataFrame,
    field_sweep: pd.DataFrame,
    metrics: pd.DataFrame,
    diagnostics: pd.DataFrame,
    best_config: FieldConfig,
    elapsed: float,
) -> None:
    hmax = max(args.horizons)
    anchor_h = anchor_metrics[(anchor_metrics["method"].eq("final_v52_anchor_test")) & (anchor_metrics["horizon"].eq(hmax))]
    anchor_component = float(anchor_h.iloc[0]["component_rmse"])
    anchor_vector = float(anchor_h.iloc[0]["vector_rmse"])
    # `metrics` already contains the exact same-row anchor.  Keeping a single
    # copy avoids changing rankings or apparent sample counts in the report.
    all_metrics = metrics.copy()
    h6 = all_metrics[all_metrics["horizon"].eq(hmax)].sort_values("component_rmse") if not all_metrics.empty else pd.DataFrame()
    best = h6.iloc[0] if not h6.empty else None
    gain = (anchor_component - float(best["component_rmse"])) / max(anchor_component, EPS) * 100.0 if best is not None else 0.0
    test_field = field_sweep[(field_sweep["split"].eq("test")) & (field_sweep["config"].eq(best_config.name))]
    real_field = test_field[test_field["control"].eq("real")]
    shared = float(real_field.iloc[0].get(f"explained_step{hmax}", np.nan)) if not real_field.empty else float("nan")
    hard_pass = bool(gain >= float(args.hard_gain_pct))
    soft_pass = bool(gain >= float(args.soft_gain_pct))
    lines = [
        "# v84 Joint Innovation Field Decision Report",
        "",
        "## Metric Contract Correction",
        "",
        f"- v52 anchor h{hmax} component RMSE: `{anchor_component:.6f}`",
        f"- same rows Euclidean vector RMSE: `{anchor_vector:.6f}`",
        f"- ratio: `{anchor_vector / max(anchor_component, EPS):.6f}` (expected sqrt(2) for 2D component-vs-vector RMSE)",
        "- Historical v52 and v81/v83 RMSE values must not be compared without this conversion and identical row IDs.",
        "",
        "## Field Basis",
        "",
        f"Selected on validation: `{best_config.name}`.",
        f"Cross-cell test explained fraction at step {hmax}: `{shared:.4f}`.",
        "",
        f"## h{hmax} Ranking",
        "",
    ]
    if not h6.empty:
        cols = [c for c in ["method", "component_rmse", "vector_rmse", "r2", "cosine", "magnitude_ratio", "stage", "control", "variant", "eta"] if c in h6.columns]
        lines.append(h6[cols].head(30).to_markdown(index=False))
    lines.extend(
        [
            "",
            "## Decision",
            "",
            f"Best gain over same-row v52 anchor: `{gain:.3f}%`.",
            f"Hard pass (`>={args.hard_gain_pct}%`): `{hard_pass}`.",
            f"Soft pass (`>={args.soft_gain_pct}%`): `{soft_pass}`.",
            "",
            "Interpretation:",
        ]
    )
    if hard_pass:
        lines.append("- Shared innovation-field signal is large enough to justify a neural equivariant latent SDE and multiseed/Edge confirmation.")
    elif soft_pass:
        lines.append("- A causal field signal exists, but it is not yet a breakthrough. Continue only with the joint field model, not focal-cell reranking.")
    else:
        lines.append("- The causal innovation field does not materially improve v52. The remaining retrospective oracle gap is not recoverable by this field representation.")
    lines.extend(["", f"Elapsed: `{elapsed / 3600.0:.2f} h`."])
    (args.out_dir / "v84_decision_report.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
def run(args: argparse.Namespace) -> None:
    started = time.time()
    args.out_dir.mkdir(parents=True, exist_ok=True)
    args.anchor_cache.mkdir(parents=True, exist_ok=True)
    args.horizons = parse_ints(args.horizons)
    if bool(args.smoke):
        args.anchor_max_train_rows = min(int(args.anchor_max_train_rows or 1200), 1200)
        args.anchor_max_val_rows = min(int(args.anchor_max_val_rows or 400), 400)
        args.anchor_max_test_rows = min(int(args.anchor_max_test_rows or 600), 600)
        args.generator_max_train_rows = args.anchor_max_train_rows
        args.generator_max_val_rows = args.anchor_max_val_rows
        args.generator_max_test_rows = args.anchor_max_test_rows
        args.posterior_epochs = min(int(args.posterior_epochs), 3)
        args.student_epochs = min(int(args.student_epochs), 3)
        args.oof_fold_limit = min(max(int(args.oof_fold_limit), 1), 1)
        args.field_grids = "3"
        args.field_sigmas = "0.35"
        args.field_ridges = "0.1"

    train, val, test, anchor_metrics = build_anchor_sets(args)
    lo, scale = fit_xy_norm(train)
    best_config, field_sweep = field_config_sweep(train, val, test, args, lo, scale)
    train_frames = fit_frame_coefficients(train, best_config, lo, scale)
    val_frames = fit_frame_coefficients(val, best_config, lo, scale)
    test_frames = fit_frame_coefficients(test, best_config, lo, scale)

    field_metrics, field_diag, field_test_correction = frame_forecast_experiments(
        train, val, test, train_frames, val_frames, test_frames, best_config, lo, scale, args
    )
    cell_metrics, cell_diag = fit_cell_innovation_models(train, val, test, field_test_correction, args)
    anchor_same = pd.DataFrame(metric_rows(test, test.anchor_steps, args.horizons, "v84_v52_anchor", {"stage": "anchor"}))
    metrics = pd.concat([anchor_same, field_metrics, cell_metrics], ignore_index=True)
    diagnostics = pd.concat([field_diag, cell_diag], ignore_index=True, sort=False)

    anchor_metrics.to_csv(args.out_dir / "v84_anchor_metrics.csv", index=False)
    field_sweep.to_csv(args.out_dir / "v84_field_reconstruction.csv", index=False)
    metrics.to_csv(args.out_dir / "v84_joint_correction_metrics.csv", index=False)
    diagnostics.to_csv(args.out_dir / "v84_diagnostics.csv", index=False)
    pd.DataFrame(
        [
            {
                "dataset": args.dataset,
                "train_seq": args.train_seq,
                "val_seq": args.val_seq,
                "test_seq": args.test_seq,
                "train_rows": len(train.rows),
                "val_rows": len(val.rows),
                "test_rows": len(test.rows),
                "oof_complete": set(train.rows["sequence"].unique()) == set(parse_ints(args.train_seq)),
                "field_config": best_config.name,
                "xy_lo_x": lo[0],
                "xy_lo_y": lo[1],
                "xy_scale_x": scale[0],
                "xy_scale_y": scale[1],
                "elapsed_sec": time.time() - started,
            }
        ]
    ).to_csv(args.out_dir / "v84_data_contract.csv", index=False)
    serializable_args = {k: v for k, v in vars(args).items() if not k.startswith("_")}
    (args.out_dir / "run_config.json").write_text(json.dumps(finite_json(serializable_args), indent=2), encoding="utf-8")
    write_report(args, anchor_metrics, field_sweep, metrics, diagnostics, best_config, time.time() - started)
    print((args.out_dir / "v84_decision_report.md").read_text(encoding="utf-8"))


def parse_args() -> argparse.Namespace:
    ap = argparse.ArgumentParser(description=__doc__)
    qrc.add_common_args(ap)
    ap.set_defaults(features=v52.DEFAULT_FEATURES, out_dir=DEFAULT_OUT)

    # Exact v12/v16/v52 anchor compatibility.
    ap.add_argument("--extra-feature-grid", type=Path, default=v12.DEFAULT_OBJECT_GRID)
    ap.add_argument("--extra-feature-prefixes", type=str, default="oc_")
    ap.add_argument("--extra-feature-block-name", type=str, default="object_mask")
    ap.add_argument("--extra-feature-max-cols", type=int, default=256)
    ap.add_argument("--extra-feature-merge-all-context", type=str, default="false")
    ap.add_argument("--v10-velocity-max-cols", type=int, default=160)
    ap.add_argument("--v12-route-k", type=int, default=12)
    ap.add_argument("--v12-min-route-cluster-size", type=int, default=40)
    ap.add_argument("--v12-prior-model", type=str, default="logistic", choices=["logistic", "hgbdt"])
    ap.add_argument("--v12-prior-max-iter", type=int, default=500)
    ap.add_argument("--v12-prior-c", type=float, default=0.35)
    ap.add_argument("--v12-hgbdt-iter", type=int, default=160)
    ap.add_argument("--v12-hgbdt-lr", type=float, default=0.05)
    ap.add_argument("--v12-hgbdt-leaf-nodes", type=int, default=31)
    ap.add_argument("--v12-hgbdt-l2", type=float, default=0.02)
    ap.add_argument("--v12-max-route-features", type=int, default=768)
    ap.add_argument("--v12-include-decomposition", action="store_true")
    ap.add_argument("--v12-expert-alpha", type=float, default=300.0)
    ap.add_argument("--v12-min-expert-samples", type=int, default=80)
    ap.add_argument("--v12-error-pool-max", type=int, default=2500)
    ap.add_argument("--v12-top-route-modes", type=int, default=4)
    ap.add_argument("--v12-route-prob-power", type=float, default=1.5)
    ap.add_argument("--v12-error-noise-scale", type=float, default=0.75)
    ap.add_argument("--v12-noise-jitter", type=float, default=0.02)
    ap.add_argument("--v16c-generator-variant", type=str, default="context_velocity")
    ap.add_argument("--v16c-top-c", type=int, default=8)
    ap.add_argument("--v16c-max-context-features", type=int, default=384)
    ap.add_argument("--v16c-ridge-alphas", type=str, default="300,1000,3000,10000")
    ap.add_argument("--generator-max-train-rows", type=int, default=0)
    ap.add_argument("--generator-max-val-rows", type=int, default=0)
    ap.add_argument("--generator-max-test-rows", type=int, default=0)
    ap.add_argument("--local-ks", type=str, default="8,16,32")
    ap.add_argument("--local-radii", type=str, default="64,128,256")
    ap.add_argument("--flow-packets", type=str, default="real")
    ap.add_argument("--v70-v52-base-mix", default="expert_top8_uniform", choices=["expert_top4_uniform", "expert_top8_uniform", "expert_all_uniform"])
    ap.add_argument("--v70-v52-calibrator", default="stacked_context", choices=["stacked_context", "stacked_top_context", "correction_context"])
    ap.add_argument("--v70-v52-bounded", action=argparse.BooleanOptionalAction, default=True)
    ap.add_argument("--v70-bounded-quantile", type=float, default=0.95)
    ap.add_argument("--v70-bounded-scale", type=float, default=1.25)

    # Anchor/OFF settings. Zero means all feature-grid rows.
    ap.add_argument("--anchor-cache", type=Path, default=ROOT / "outputs" / "joint_innovation_field_v84_anchor_cache")
    ap.add_argument("--anchor-max-train-rows", type=int, default=0)
    ap.add_argument("--anchor-max-val-rows", type=int, default=0)
    ap.add_argument("--anchor-max-test-rows", type=int, default=0)
    ap.add_argument("--oof-fold-limit", type=int, default=0)
    ap.add_argument("--rebuild-anchors", action="store_true")

    # Field decomposition and causal forecast.
    ap.add_argument("--field-grids", type=str, default="3,4,5")
    ap.add_argument("--field-sigmas", type=str, default="0.2,0.3,0.4")
    ap.add_argument("--field-ridges", type=str, default="0.01,0.1,1,10")
    ap.add_argument("--field-lags", type=int, default=4)
    ap.add_argument("--field-forecast-alphas", type=str, default="0.1,1,10,100,1000")
    ap.add_argument("--correction-eta-grid", type=str, default="0,0.05,0.1,0.2,0.35,0.5,0.75,1")
    ap.add_argument("--self-innovation-lags", type=int, default=4)
    ap.add_argument("--cell-ridge-alphas", type=str, default="1,10,100,300,1000,3000")
    ap.add_argument("--soft-gain-pct", type=float, default=1.0)
    ap.add_argument("--hard-gain-pct", type=float, default=3.0)
    return ap.parse_args()


def main() -> None:
    args = parse_args()
    started = time.time()
    try:
        run(args)
    except Exception as exc:
        args.out_dir.mkdir(parents=True, exist_ok=True)
        payload = {"ok": False, "error": repr(exc), "traceback": traceback.format_exc(), "elapsed_sec": time.time() - started}
        (args.out_dir / "v84_error.json").write_text(json.dumps(finite_json(payload), indent=2), encoding="utf-8")
        print(payload["traceback"], file=sys.stderr)
        raise


if __name__ == "__main__":
    main()
